param(
    [Parameter(Mandatory=$false)]
    [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"

$expectedHead = "0a8d1e56d7fbfe777150edd0e07321ecdbd9f89f"
$expectedBranch = "master"
$expectedVersion = "0.2.21"

function Assert-Exit([string]$Message) {
    if ($LASTEXITCODE -ne 0) { throw $Message }
}

function Ensure-DesktopDependencies([string]$Root) {
    $desktop = Join-Path $Root "desktop"
    if (-not (Test-Path (Join-Path $desktop "node_modules\.bin\tsc.cmd")) -and
        -not (Test-Path (Join-Path $desktop "node_modules\.bin\tsc"))) {
        Write-Host "Desktop dependencies missing in sandbox; running npm ci..."
        Push-Location $desktop
        try {
            npm ci
            Assert-Exit "npm ci failed"
        }
        finally { Pop-Location }
    }
}

function Assert-SourceGuards([string]$Root) {
    $generator = Get-Content (Join-Path $Root "dependency_live_roadmap_generator.py") -Raw -Encoding UTF8
    $main = Get-Content (Join-Path $Root "desktop\electron\main.ts") -Raw -Encoding UTF8

    foreach ($required in @(
        "_proof_preserving_minimize_nogood",
        "constraint-minimization-completed",
        "BASELINE_VERIFICATION_PLATEAU",
        "BASELINE_VERIFICATION_HARD_BUDGET_EXHAUSTED",
        "BASELINE_SOLVER_REPEATED_FAILED_ASSIGNMENT"
    )) {
        if (-not $generator.Contains($required)) {
            throw "BLOCK F source guard missing: $required"
        }
    }

    foreach ($required in @(
        "BASELINE_VERIFICATION_PLATEAU",
        "BASELINE_VERIFICATION_HARD_BUDGET_EXHAUSTED",
        "BASELINE_SOLVER_REPEATED_FAILED_ASSIGNMENT",
        "BASELINE_CONSTRAINT_MINIMIZATION_INCONCLUSIVE"
    )) {
        if (-not $main.Contains($required)) {
            throw "BLOCK F Electron non-retryable guard missing: $required"
        }
    }
}

function Assert-SandboxShape([string]$Root) {
    $untracked = @(git -C $Root ls-files --others --exclude-standard)
    if ($LASTEXITCODE -ne 0) { throw "Could not inspect sandbox untracked files" }
    if ($untracked.Count -gt 0) {
        throw "BLOCK F introduced unexpected untracked files: $($untracked -join ', ')"
    }

    $changed = @(git -C $Root diff --name-only HEAD)
    if ($LASTEXITCODE -ne 0) { throw "Could not inspect sandbox tracked diff" }

    $expected = @(
        "dependency_live_roadmap_generator.py",
        "tests/test_adaptive_graph_generalization.py",
        "desktop/electron/main.ts",
        "desktop/scripts/check-run-monitor.mjs"
    )
    $unexpected = @($changed | Where-Object { $_ -and $_ -notin $expected })
    $missing = @($expected | Where-Object { $_ -notin $changed })
    if ($unexpected.Count -gt 0 -or $missing.Count -gt 0) {
        throw "BLOCK F sandbox diff shape mismatch. changed=$($changed -join ', ')"
    }
}

function Run-Gates([string]$Root, [string]$Label) {
    Push-Location $Root
    try {
        Write-Host ""
        Write-Host "== $Label targeted Block F tests =="
        python -m unittest discover -s tests -p "test_adaptive_graph_generalization.py" -v
        Assert-Exit "$Label targeted Block F tests failed"

        Write-Host ""
        Write-Host "== $Label full Python/tool suite =="
        python run_tool_tests.py --suite all
        Assert-Exit "$Label full Python/tool suite failed"

        python -m py_compile dependency_live_roadmap_generator.py
        Assert-Exit "$Label generator py_compile failed"

        Assert-SourceGuards $Root
        Ensure-DesktopDependencies $Root

        Push-Location (Join-Path $Root "desktop")
        try {
            Write-Host ""
            Write-Host "== $Label Desktop deterministic-stop contracts =="
            npm run check:run-monitor
            Assert-Exit "$Label check:run-monitor failed"

            npm run build
            Assert-Exit "$Label desktop build failed"

            npm run lint
            Assert-Exit "$Label desktop lint failed"
        }
        finally { Pop-Location }

        git diff --check
        Assert-Exit "$Label git diff --check failed"
    }
    finally { Pop-Location }
}

$RepoRoot = (Resolve-Path $RepoRoot).Path
$sandbox = Join-Path $env:TEMP ("deploom-block-f-" + [guid]::NewGuid().ToString("N"))
$tempPy = Join-Path $env:TEMP ("deploom-block-f-transform-" + [guid]::NewGuid().ToString("N") + ".py")
$patch = Join-Path $env:TEMP ("deploom-block-f-" + [guid]::NewGuid().ToString("N") + ".patch")
$sandboxAdded = $false

$payload = @'

'@

Write-Host "== DepLoom BLOCK F: Proof-strengthening + Semantic Convergence =="
Write-Host "Base: origin/master v$expectedVersion @ $expectedHead"
Write-Host ""
Write-Host "Proof model:"
Write-Host "  diagnostic ordering/ddmin never becomes authority"
Write-Host "  every accepted literal shrink gets fresh serial verification"
Write-Host "  the exact authoritative failure predicate must remain stable"
Write-Host "  only the minimized, certified clause enters Solver/cache"
Write-Host ""

try {
    [System.IO.File]::WriteAllBytes(
        $tempPy,
        [Convert]::FromBase64String(($payload -replace '\s+', ''))
    )
    python -m py_compile $tempPy
    Assert-Exit "Embedded BLOCK F transformer does not compile"

    Push-Location $RepoRoot
    try {
        $branch = (git branch --show-current).Trim()
        Assert-Exit "Could not read current branch"
        if ($branch -ne $expectedBranch) {
            throw "BLOCK F requires branch '$expectedBranch'; current branch='$branch'"
        }

        $head = (git rev-parse HEAD).Trim()
        Assert-Exit "Could not read HEAD"
        $originHead = (git rev-parse origin/master).Trim()
        Assert-Exit "Could not read origin/master"

        if ($head -ne $originHead) {
            throw "Local master is not identical to origin/master. local=$head origin/master=$originHead"
        }
        if ($head -ne $expectedHead) {
            throw "BLOCK F is bound to v$expectedVersion $expectedHead; current origin/master=$head"
        }

        $version = (Get-Content ".\VERSION" -Raw -Encoding UTF8).Trim()
        if ($version -ne $expectedVersion) {
            throw "Expected VERSION=$expectedVersion, got $version"
        }

        git diff --quiet
        Assert-Exit "Tracked working tree is dirty. Commit/stash tracked changes first."
        git diff --cached --quiet
        Assert-Exit "Index is not clean."

        Write-Host "== Detached sandbox from exact origin/master =="
        git worktree add --quiet --detach $sandbox $expectedHead
        Assert-Exit "Could not create detached BLOCK F sandbox"
        $sandboxAdded = $true

        Write-Host ""
        Write-Host "== Sandbox transform =="
        python $tempPy $sandbox
        Assert-Exit "BLOCK F transform failed; real checkout untouched"

        Assert-SandboxShape $sandbox
        Assert-SourceGuards $sandbox
        Run-Gates $sandbox "Sandbox"

        git -C $sandbox diff --binary HEAD --output=$patch
        Assert-Exit "Could not export tested BLOCK F patch"
        if (-not (Test-Path $patch) -or (Get-Item $patch).Length -eq 0) {
            throw "Sandbox produced an empty patch"
        }

        Write-Host ""
        Write-Host "== SANDBOX BLOCK F PASS =="
        Write-Host "Applying the exact tested patch to real master..."

        git apply --check $patch
        Assert-Exit "Tested BLOCK F patch does not apply cleanly to real checkout"
        git apply $patch
        Assert-Exit "Could not apply tested BLOCK F patch"

        Run-Gates $RepoRoot "Real"

        Write-Host ""
        Write-Host "== BLOCK F PASS =="
        Write-Host "Implemented and verified:"
        Write-Host "  - bounded literal-level proof-preserving ddmin (max 12 fresh checks)"
        Write-Host "  - graph generalized constraints minimized before Solver authority"
        Write-Host "  - localized constraints re-certified/minimized before Solver/cache"
        Write-Host "  - accepted shrink must preserve the same authoritative predicate"
        Write-Host "  - shrink history/check telemetry"
        Write-Host "  - repeated confirmed failing assignment => Solver invariant failure"
        Write-Host "  - semantic PLATEAU vs absolute HARD_BUDGET_EXHAUSTED"
        Write-Host ""
        Write-Host "No commit, tag, or push was performed."
        Write-Host "This is the milestone for a full partner-form Baseline run."
    }
    finally { Pop-Location }
}
finally {
    if ($sandboxAdded -and (Test-Path $sandbox)) {
        git -C $RepoRoot worktree remove --force $sandbox 2>$null | Out-Null
    }
    elseif (Test-Path $sandbox) {
        Remove-Item $sandbox -Recurse -Force -ErrorAction SilentlyContinue
    }
    git -C $RepoRoot worktree prune 2>$null | Out-Null
    Remove-Item $tempPy -Force -ErrorAction SilentlyContinue
    Remove-Item $patch -Force -ErrorAction SilentlyContinue
}
